"""Kern pairs for the faces this library measures with.

PowerPoint lays text out with the face's OpenType ``kern`` feature applied and, until
this table existed, we did not: every line we measured was *wider* than the one
PowerPoint drew.  The error is small per pair and compounds down a line -- 0% to 0.684%
over ``sample-cjk``'s fifteen lines, and 1.5% for a string of nothing but kerned pairs
(キスキスキス) -- which is exactly the shape of error that breaks a line one character
early and then does it again on the next line.  ``text/wrap.py``'s
``WRAP_TOLERANCE_RATIO`` existed only to absorb it.

Like :mod:`pptx2svg.text.metrics`, this is *generated* -- by ``tools/extract_font_metrics.py``
from the same font files the rasteriser is handed -- and for the same reason: a hand-kept
table drifts from the face silently.  **A kern value is a measurement, not font
software**, which is the footing the Office faces' advance widths already stand on; no
font file is redistributed to carry one.

Why a class matrix rather than a list of pairs
----------------------------------------------

A face carries thousands of kern pairs and this is source code a human reads, so the
representation was measured before it was chosen.  Over the twenty face-and-weight tables
below, restricted to the characters :mod:`pptx2svg.text.metrics` stores advances for:

=================================  =========================  ==========
representation                     entries                    source
=================================  =========================  ==========
one entry per pair                 276,551 pairs              ~6.1 MB
class matrix (this file)           28,406 cells + 8,511        416 KB
                                   class members
=================================  =========================  ==========

Fifteen times smaller, and *exact*: nothing is rounded, dropped or approximated.  The
compression is real because kerning is designed that way -- ``A`` kerns against ``V``
because of what the two shapes are, and ``À Á Â Ã Ä Å Ā Ă Ą`` all have ``A``'s shape.
Rounding the values to 1/1000 em before classifying was tried, on the theory that coarser
values would merge more classes; it merges 133 cells of 28,406 and saves 2% of the file,
because the classes here *are* the font's design classes and a rounding does not merge
two of them.  So the values stay in font units, exactly as the advance widths do.

The classes here are **not** the font's own ``ClassDef`` tables.  They are re-derived
from the kern *function* itself: two characters share a left class when they kern
identically against every character, and likewise on the right.  That matters because the
faces are not all class-based -- Arimo and Tinos store explicit pairs (``PairPos``
format 1), Carlito stores a class matrix (format 2), Lato and Cambria mix the two, and
Cambria, Aptos and Aptos Display also carry a legacy ``kern`` table.  Re-deriving from
the function makes all five cases come out the same shape, and the generator asserts the
round trip pair for pair.

Class 0 is "kerns with nothing" and is not written down: a character absent from
:attr:`KernTable.left` never kerns as a left-hand member, which is most of them.

What is *not* here
------------------

* **Ideographs.**  No face in this table kerns a kanji, checked against a hundred common
  ones in every face; ``metrics.cjk_width`` remains their whole story.  Kana, CJK
  punctuation and full-width forms do kern and are covered.
* **Faces with no kern feature at all** get no entry -- eighteen of the twenty-eight:
  Cousine, the four MS Japanese faces, the eleven fixed-pitch CJK faces and the two
  Lucida monospaces.  Monospace and full-width designs do not kern, which is a fact
  about them rather than a gap here.
* **Chart text.**  :func:`pptx2svg.resolve.chart.text_width` deliberately does not
  consult this table: PowerPoint's chart engine lays its text out with plain advances
  and draws it kerned, which is measured on its own export.  See that function.
* **Cross-face pairs.**  Kerning is a property of one face, so a pair that straddles the
  Latin/East-Asian split in :func:`pptx2svg.text.measure.is_cjk` -- where the two
  characters are measured from *different* tables -- gets none.  That is what a shaper
  does too: it breaks the run at the font boundary.

Values are in font units, on the same ``units_per_em`` as the advance widths beside them;
divide by ``units_per_em`` and multiply by the pixel size.
"""

from __future__ import annotations

from dataclasses import dataclass, field


@dataclass(frozen=True)
class KernTable:
    """One face's kern pairs, upright and bold, as a class matrix.

    ``left[i]`` is the set of characters in left class ``i + 1`` -- class 0 is the
    implicit "kerns with nothing" -- and ``right`` the same on the other side.
    ``matrix`` is keyed ``left class -> right class -> adjustment``, sparse in both.
    """

    left: tuple[str, ...] = ()
    right: tuple[str, ...] = ()
    matrix: dict = field(default_factory=dict)
    #: Bold equivalents.  Empty for a face whose bold cut we do not measure, in which case
    #: :meth:`adjustment` falls back to the upright classes -- the same rule
    #: :class:`~pptx2svg.text.metrics.FontMetrics` uses for advance widths.
    bold_left: tuple[str, ...] = ()
    bold_right: tuple[str, ...] = ()
    bold_matrix: dict = field(default_factory=dict)

    def adjustment(self, left_char: str, right_char: str, bold: bool = False) -> int:
        """The ``kern`` adjustment between two adjacent characters, in font units.

        Zero -- by far the common answer -- costs two dict lookups and no tuple.
        """
        left_index, right_index, matrix = self._index(bold)
        first = left_index.get(left_char)
        if first is None:
            return 0
        second = right_index.get(right_char)
        if second is None:
            return 0
        return matrix.get(first, {}).get(second, 0)

    def _index(self, bold: bool):
        """Character -> class id, inverted from the class strings on first use.

        Built lazily and cached on the instance: a deck touches two or three faces and
        the tables run to a few hundred classes each.  ``frozen=True``, so the cache goes
        in through ``__dict__`` the same way
        :meth:`~pptx2svg.text.metrics.FontMetrics.bold_is_indistinguishable` does.
        """
        slot = "_bold_index" if bold and self.bold_left else "_index_cache"
        cached = self.__dict__.get(slot)
        if cached is None:
            if bold and self.bold_left:
                left, right, matrix = self.bold_left, self.bold_right, self.bold_matrix
            else:
                left, right, matrix = self.left, self.right, self.matrix
            cached = (_invert(left), _invert(right), matrix)
            object.__setattr__(self, slot, cached)
        return cached


def _invert(classes: tuple[str, ...]) -> dict[str, int]:
    return {char: index for index, group in enumerate(classes, 1) for char in group}


